// KNN-7 Direction Vote 3D
// KNN nearest-neighbour vote on next-bar direction (Euclidean on returns)

kIn = input(7, "K Neighbors", 1, 30, 1)
featWin = input(20, "Feature Window", 5, 40, 1)
histLook = input(200, "History Lookback", 50, 500, 10)
marginThresh = input(0.43, "Margin Threshold", 0.05, 1.0, 0.01)
disThresh = input(0.35, "Disagreement Threshold", 0.05, 1.0, 0.01)
minHist = input(50, "Min History Bars", 20, 200, 1)

// ─── Per-bar return ────────────────────────────────────────
rCur = 0.0
if close[1] != 0 {
    rCur := (close - close[1]) / close[1]
}

// ─── Persistent return + close history ─────────────────────
varip retHist = array(0)
varip closeHist = array(0)
array.push(retHist, rCur)
array.push(closeHist, close)

// ─── KNN vote channels ─────────────────────────────────────
margin = 0.0
disagree = 1.0
upVotes = 0
downVotes = 0

nBars = array.size(retHist)
ready = bar_index >= minHist and nBars >= featWin + 2 and nBars >= minHist

if ready {
    // current feature window: last featWin returns ending at nBars-1
    bestDist = array()
    bestLab = array()
    b = 0
    while b < kIn {
        array.push(bestDist, 999999.0)
        array.push(bestLab, 0)
        b := b + 1
    }

    // candidate range: [nBars-1-histLook, nBars-2] to avoid overlap with future
    searchStart = nBars - 1 - histLook
    if searchStart < featWin - 1 { searchStart := featWin - 1 }
    searchEnd = nBars - 2

    j = searchStart
    while j <= searchEnd {
        // Euclidean distance over featWin returns: cur window vs window ending at j
        // label for j uses next-bar direction: closeHist[j+1] vs closeHist[j]
        d2 = 0.0
        f = 0
        while f < featWin {
            a = retHist[nBars - featWin + f]
            c = retHist[j - featWin + 1 + f]
            diff = a - c
            d2 := d2 + diff * diff
            f := f + 1
        }
        dist = sqrt(d2)

        lab = -1
        if closeHist[j + 1] > closeHist[j] { lab := 1 }

        // insertion into k-smallest sorted list
        insIdx = -1
        m = 0
        while m < kIn {
            if dist < bestDist[m] {
                insIdx := m
                m := kIn
            }
            m := m + 1
        }
        if insIdx >= 0 {
            m = kIn - 1
            while m > insIdx {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestLab, m, bestLab[m - 1])
                m := m - 1
            }
            array.set(bestDist, insIdx, dist)
            array.set(bestLab, insIdx, lab)
        }
        j := j + 1
    }

    // Channel 1 - Vote Margin: (Up - Down) / k
    up = 0
    dn = 0
    valid = 0
    m = 0
    while m < kIn {
        if bestDist[m] < 999999.0 {
            valid := valid + 1
            if bestLab[m] == 1 { up := up + 1 }
            else { dn := dn + 1 }
        }
        m := m + 1
    }
    upVotes := up
    downVotes := dn
    if valid > 0 {
        margin := (up - dn) / valid
    }

    // Channel 2 - Neighbour Disagreement: sdD / (meanD + 1e-9)
    meanD = 0.0
    m = 0
    while m < kIn {
        meanD := meanD + bestDist[m]
        m := m + 1
    }
    if valid > 0 { meanD := meanD / valid }
    varD = 0.0
    m = 0
    while m < kIn {
        if bestDist[m] < 999999.0 {
            dd = bestDist[m] - meanD
            varD := varD + dd * dd
        }
        m := m + 1
    }
    if valid > 0 { varD := varD / valid }
    sdD = sqrt(varD)
    disagree := sdD / (meanD + 0.000000001)
}

// ─── Signal rules: both channels must agree ────────────────
buyCond = ready and margin > marginThresh and disagree < disThresh
sellCond = ready and margin < 0 - marginThresh and disagree < disThresh

var lastSig = 0
sigNow = 0
if buyCond { sigNow := 1 }
if sellCond { sigNow := 0 - 1 }

buySig = buyCond and lastSig <= 0
sellSig = sellCond and lastSig >= 0
if sigNow != 0 { lastSig := sigNow }

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

// ─── 2D channels: independently readable ───────────────────
plot(margin, "Vote Margin", "#22cc88", 2, "separate")
plot(disagree, "Disagreement", "#ff4477", 1, "separate")
hline(0, "#888888", "separate")
hline(marginThresh, "rgba(34,204,136,0.5)", "separate")
hline(0 - marginThresh, "rgba(255,68,119,0.5)", "separate")
hline(disThresh, "rgba(255,212,59,0.5)", "separate")

// ─── 3D form: bars height = margin (front face), ribbon = disagreement (depth) ───
// Crisp = tall thin tower + flat ribbon. Contested = short slab + raised ribbon.
plot3d(margin, "Vote Margin Towers", "bars3d", "#22cc88", "separate")
plot3d(disagree, "Disagreement Depth", "ribbon", "#ffd43b", "separate", 1)

// Visible Session Value Terrain Model
// Volume-profile-at-price over the visible session: POC + value area,
// breakout/breakdown when price leaves value. 2D lines carry POC/VAH/VAL,
// 3D separate-pane terrain shows where value sits with a labelled POC rail.

rows = input(50, "Rows", 10, 100, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 1)
lookback = input(120, "Session Lookback Bars", 30, 300, 5)
heightScale = input(1.0, "Terrain Height Scale", 0.2, 3.0, 0.1)
showVA = input(true, "Show Value Area")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session range ───────────────────────────────────────────────
hh = highest(high, lookback)
ll = lowest(low, lookback)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
binH = rng / rows

// ─── Persistent bins (literal init only, resized to Rows) ────────
var binVol = array()
if array.size(binVol) == 0 {
    k = 0
    while k < 100 {
        array.push(binVol, 0.0)
        k := k + 1
    }
}

// Zero the active Rows bins every bar (recomputed window, no freeze)
i = 0
while i < rows {
    array.set(binVol, i, 0.0)
    i := i + 1
}

// ─── Distribute each bar's volume across overlapped bins ──────────
j = 0
while j < lookback {
    bh = high[j]
    bl = low[j]
    bv = volume[j]
    brng = bh - bl
    if brng <= 0 {
        cb = close[j]
        bi = floor((cb - ll) / rng * rows)
        if bi < 0 {
            bi := 0
        }
        if bi > rows - 1 {
            bi := rows - 1
        }
        array.set(binVol, bi, array.get(binVol, bi) + bv)
    } else {
        b = 0
        while b < rows {
            binLo = ll + b * binH
            binHi = binLo + binH
            top = bh
            if binHi < top {
                top := binHi
            }
            bot = bl
            if binLo > bot {
                bot := binLo
            }
            ov = top - bot
            if ov > 0 {
                share = ov / brng
                array.set(binVol, b, array.get(binVol, b) + bv * share)
            }
            b := b + 1
        }
    }
    j := j + 1
}

// ─── POC: bin with max volume ────────────────────────────────────
pocBin = 0
pocVal = array.get(binVol, 0)
i2 = 1
while i2 < rows {
    v = array.get(binVol, i2)
    if v > pocVal {
        pocVal := v
        pocBin := i2
    }
    i2 := i2 + 1
}
totalVol = 0.0
i3 = 0
while i3 < rows {
    totalVol := totalVol + array.get(binVol, i3)
    i3 := i3 + 1
}
pocPrice = ll + (pocBin + 0.5) * binH

// ─── Value area: expand from POC until Value Area Percent held ───
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < rows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(binVol, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < rows - 1 {
        rightVal := array.get(binVol, vaHigh + 1)
    }
    if rightVal >= leftVal {
        if vaHigh < rows - 1 {
            vaHigh := vaHigh + 1
            accum := accum + rightVal
        } else {
            if vaLow > 0 {
                vaLow := vaLow - 1
                accum := accum + leftVal
            }
        }
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        } else {
            if vaHigh < rows - 1 {
                vaHigh := vaHigh + 1
                accum := accum + rightVal
            }
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) * binH
valPrice = ll + vaLow * binH

// ─── Position relative to value + signals ────────────────────────
insideVA = close >= valPrice and close <= vahPrice
prevClose = close[1]
prevInside = prevClose >= valPrice and prevClose <= vahPrice
buySig = prevInside and close > vahPrice
sellSig = prevInside and close < valPrice

// 3D terrain heights derived ONLY from bin volumes (no outside family)
terrainPeak = 0.0
if totalVol > 0 {
    terrainPeak := pocVal / totalVol * 100 * heightScale
}
vaShare = 0.0
if totalVol > 0 {
    vaShare := accum / totalVol * 100
}
coneSz = 0.6 + terrainPeak / 100 * 1.6
if coneSz > 2.2 {
    coneSz := 2.2
}
coneSz := coneSz * markerSize

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

// 3D cones in the SAME separate pane (zone-gated, no every-bar paint)
if buySig {
    plotshape_3d(bar_index, terrainPeak, "Buy", "coneup", "#22cc88", coneSz, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, terrainPeak, "Sell", "conedown", "#ff4477", coneSz, 0, "separate")
}

// Label the rail only when a NEW POC bin is established (rare, readable)
var wasPoc = -1
if pocBin != wasPoc {
    label3d(bar_index, terrainPeak, "POC", "#ffd43b", 1.2, 2, "separate")
}
wasPoc := pocBin

// ─── 2D: identical POC price + value zone when 3D is off ─────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
fill(vahPrice, valPrice, "rgba(68,136,255,0.12)")
plot(terrainPeak, "Peak Concentration", "#4488ff", 1, "separate")
plot(vaShare, "Value Share", "#22cc88", 1, "separate")

// ─── 3D: value terrain surface + POC rail (same separate pane) ───
plot3d(terrainPeak, "Value Terrain", "surface", "#4488ff", "separate", 0)
plot3d(vaShare, "Value Area Sheet", "manifold", "#22cc88", "separate", 1)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "separate", 2)

if showVA {
    if insideVA {
        bgcolor("rgba(68,136,255,0.05)")
    }
}

// Fix 1: var lvl = highest(high, 20) froze at bar 0 -> plain assignment recomputed every bar.
// Fix 2: close[-1] read one bar into the future -> close with no lookahead.
// Fix 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine form -> plotshape(bar_index, low, "Buy", "triangleup", "#22cc88").
// Fix 4: RSI oscillator forced into pane "3d" renders as spiky forest over price -> pane "separate".
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot3d(r, "RSI", "surface", "#b48cff", "separate")
